#include <mutex>
#include <atomic>

class Counter {
private:
    mutable std::mutex mtx; // For thread-safe mutation
    mutable int computations_ = 0;
    mutable std::atomic<int> atomic_calls_ = 0;

public:
    // Unsafe: Data race if called from multiple threads
    int unsafe_get_value() const {
        return computations_; // Read is fine, but if we had mutable writes...
    }

    // Safe: Uses a mutex to protect access to mutable data
    void safe_computation() const {
        std::lock_guard<std::mutex> lock(mtx);
        ++computations_; // Safe to modify mutable member
    }

    // Safe: Uses std::atomic for lock-free updates
    void atomic_increment() const {
        atomic_calls_++; // Atomic operation is thread-safe
    }
};
